function setup(){
  createCanvas(600, 600);
}

function draw(){
  translate(width/2,height/2);
  background(220);
  for(let i=0; i<4; i++){
   fractal(6,100.0,5.0);
   rotate(TWO_PI/4);
  }
}

function fractal(n, l,sw){
  if(n==0) return;
  else{
    for(let i=0; i<3; i++){
      push();
      rotate(radians(-45+45*i+20*sin(PI/300*frameCount)));
      strokeWeight(sw);
      line(0,0,0,-l);
      translate(0,-l);
      fractal(n-1,2*l/3,sw/2);
      pop();
    }
  }
}
